window.futvizVista("perfil-ofensivo","<div class=\"rx-mount\" data-rx=\"scatter\" data-rx-id=\"perfil-ofensivo\" style=\"min-height:520px\"></div><script>(window.futvizVistas=window.futvizVistas||{})[\"perfil-ofensivo\"]={\"id\":\"perfil-ofensivo\",\"titulo\":\"Perfil ofensivo: xG90 vs. xA90\",\"bajada\":\"A la derecha, m\u00e1s xG por 90' (remata); arriba, m\u00e1s xA por 90' (crea). Abre con medios y delanteros.\",\"pregunta\":\"\u00bfQui\u00e9n remata y qui\u00e9n crea?\",\"tabla\":\"jugadores\",\"entidad\":\"jugadores\",\"x\":{\"col\":\"xG90\",\"label\":\"xG por 90'\",\"corto\":\"xG90\",\"dec\":2},\"y\":{\"col\":\"xA90\",\"label\":\"xA por 90'\",\"corto\":\"xA90\",\"dec\":2},\"referencia\":{\"tipo\":\"promedios\",\"cuadrantes\":{\"tl\":\"Crean mucho pero rematan poco\",\"tr\":\"Crean y rematan mucho\",\"br\":\"Rematan mucho pero crean poco\",\"bl\":\"Crean y rematan poco\"},\"cuantil\":0.8},\"requiere\":[\"xG90\",\"xA90\"],\"subtitulo\":\"Jugadores con \u2265{min} min \u00b7 {temporada}\",\"filtros\":{\"posicion\":true,\"nivel\":true,\"sub21\":true},\"metricas\":[{\"id\":\"x\",\"etiqueta\":\"xG90\",\"ayuda\":\"Ordenados por xG por 90'\"},{\"id\":\"y\",\"etiqueta\":\"xA90\",\"ayuda\":\"Ordenados por xA por 90'\"}],\"queMirar\":\"Ubica a cada jugador seg\u00fan lo que genera con sus tiros y con sus pases, por 90 minutos. El eje horizontal es el xG, el peligro de sus remates, y el vertical es el xA, el peligro de los pases con los que habilita a otros.\\nLas l\u00edneas marcan el 20% m\u00e1s alto de cada eje, as\u00ed que pasar una de ellas indica que el jugador destaca en esa faceta, y arriba a la derecha est\u00e1n los que destacan en las dos.\",\"insight\":\"perfil\",\"fuente\":\"Understat\",\"colorPor\":[\"liga\"],\"posicionesIni\":[\"Medio\",\"Delantero\"]};</script>");